import os
import numpy as np
import pandas as pd
import matplotlib
import matplotlib.pyplot as plt
import japanize_matplotlib
from scipy import stats
plt.rcParams["font.size"] = 20
plt.rcParams['text.usetex'] = True
import warnings
warnings.simplefilter('ignore')

table = pd.DataFrame(np.zeros((45, 15)))

for ind1 in range(5):
    n = [25,50,100,200,400][ind1]
    for ind2 in range(5):
        r = [.1,.3,.5,.7,.9][ind2]
        for ind3 in range(3):
            T = [1,5,25][ind3]
            res = np.zeros((1000,10,32))
            result = np.zeros((1000,20,16))
            for seed in range(1000):
                res[seed] = np.loadtxt("Results-sq/%d-%f-%d/error-%d-%f-%d-%d.csv"%(n,r,T,n,r,T,seed), delimiter=",")#np.nan_to_num(, posinf=1.**20)
                for k in range(10):
                    if np.all(res[seed,k,:] == 0):
                        res[seed,k,:16] = res[seed,k-1,16:]
                        res[seed,k,16:] = res[seed,k-1,16:]
            for k in range(10):
                result[:,2*k,:] = res[:,k,:16]
                result[:,2*k+1,:] = res[:,k,16:]
            #
            res2 = np.zeros((1000,10,32))
            result2 = np.zeros((1000,20,16))
            for seed in range(1000):
                res2[seed] = np.loadtxt("Results-sq2/%d-%f-%d/error-%d-%f-%d-%d.csv"%(n,r,T,n,r,T,seed), delimiter=",")#np.nan_to_num(, posinf=1.**20)
                for k in range(10):
                    if np.all(res2[seed,k,:] == 0):
                        res2[seed,k,:16] = res2[seed,k-1,16:]
                        res2[seed,k,16:] = res2[seed,k-1,16:]
            for k in range(10):
                result2[:,2*k,:] = res2[:,k,:16]
                result2[:,2*k+1,:] = res2[:,k,16:]
            #
            BT  = result[:,0,:]
            IBT = np.zeros((1000,16))
            for i in range(1000):
                IBT[i,1] = result[i,np.argmin(result2[i,:,1]),1]
                # IBT[i,5] = result[i,np.argmax(result2[i,:,5]),5]
                # IBT[i,7] = result[i,np.argmax(result2[i,:,7]),7]
                # IBT[i,1] = result[i,19-np.argmin(result2[i,:,1][::-1]),1]
                IBT[i,5] = result[i,19-np.argmax(result2[i,:,5][::-1]),5]
                IBT[i,7] = result[i,19-np.argmax(result2[i,:,7][::-1]),7]

            test1 = stats.mannwhitneyu(IBT[:,1], BT[:,1], alternative='less')
            test5 = stats.mannwhitneyu(IBT[:,5], BT[:,5], alternative='greater')
            test7 = stats.mannwhitneyu(IBT[:,7], BT[:,7], alternative='greater')

            # print(n,r,T,",",
            #     "$%.4f-%.4f$"%(np.mean(BT[:,1]),np.std(BT[:,1])),
            #     "$%.4f-%.4f$"%(np.mean(IBT[:,1]),np.std(IBT[:,1])),"(%.4f),"%test1.pvalue,
            #     "$%.4f-%.4f$"%(np.mean(BT[:,5]),np.std(BT[:,5])),
            #     "$%.4f-%.4f$"%(np.mean(IBT[:,5]),np.std(IBT[:,5])),"(%.4f),"%test5.pvalue,
            #     "$%.4f-%.4f$"%(np.mean(BT[:,7]),np.std(BT[:,7])),
            #     "$%.4f-%.4f$"%(np.mean(IBT[:,7]),np.std(IBT[:,7])),"(%.4f),"%test7.pvalue)
            if test1.pvalue<.05:
                table.iloc[   3*ind1  ,5*ind3+ind2] = "\\tcr{$%.4f_{%.4f}$}"%(np.mean(BT[:,1]),np.std(BT[:,1]))
                table.iloc[   3*ind1+1,5*ind3+ind2] = "\\tcr{$%.4f_{%.4f}$}"%(np.mean(IBT[:,1]),np.std(IBT[:,1]))
                table.iloc[   3*ind1+2,5*ind3+ind2] = "(\\tcr{$%.4f$})"%test1.pvalue
            else:
                table.iloc[   3*ind1  ,5*ind3+ind2] = "$%.4f_{%.4f}$"%(np.mean(BT[:,1]),np.std(BT[:,1]))
                table.iloc[   3*ind1+1,5*ind3+ind2] = "$%.4f_{%.4f}$"%(np.mean(IBT[:,1]),np.std(IBT[:,1]))
                table.iloc[   3*ind1+2,5*ind3+ind2] = "($%.4f$)"%test1.pvalue
            if test5.pvalue<.05:
                table.iloc[15+3*ind1  ,5*ind3+ind2] = "\\tcr{$%.4f_{%.4f}$}"%(np.mean(BT[:,5]),np.std(BT[:,5]))
                table.iloc[15+3*ind1+1,5*ind3+ind2] = "\\tcr{$%.4f_{%.4f}$}"%(np.mean(IBT[:,5]),np.std(IBT[:,5]))
                table.iloc[15+3*ind1+2,5*ind3+ind2] = "(\\tcr{$%.4f$})"%test5.pvalue
            else:
                table.iloc[15+3*ind1  ,5*ind3+ind2] = "$%.4f_{%.4f}$"%(np.mean(BT[:,5]),np.std(BT[:,5]))
                table.iloc[15+3*ind1+1,5*ind3+ind2] = "$%.4f_{%.4f}$"%(np.mean(IBT[:,5]),np.std(IBT[:,5]))
                table.iloc[15+3*ind1+2,5*ind3+ind2] = "($%.4f$)"%test5.pvalue
            if test7.pvalue<.05:
                table.iloc[30+3*ind1  ,5*ind3+ind2] = "\\tcr{$%.4f_{%.4f}$}"%(np.mean(BT[:,7]),np.std(BT[:,7]))
                table.iloc[30+3*ind1+1,5*ind3+ind2] = "\\tcr{$%.4f_{%.4f}$}"%(np.mean(IBT[:,7]),np.std(IBT[:,7]))
                table.iloc[30+3*ind1+2,5*ind3+ind2] = "(\\tcr{$%.4f$})"%test7.pvalue
            else:
                table.iloc[30+3*ind1  ,5*ind3+ind2] = "$%.4f_{%.4f}$"%(np.mean(BT[:,7]),np.std(BT[:,7]))
                table.iloc[30+3*ind1+1,5*ind3+ind2] = "$%.4f_{%.4f}$"%(np.mean(IBT[:,7]),np.std(IBT[:,7]))
                table.iloc[30+3*ind1+2,5*ind3+ind2] = "($%.4f$)"%test7.pvalue

for i in range(45):
    for j in range(15):
        print(end="&")
        print(table.iloc[i,j],end="")
    print("\\\\")

